<script setup lang="ts">
import { RouterLink } from 'vue-router'
import { issueItemLabels, type IssueItemKind, type IssuePackage, type PackageItem } from '../../api/issuance'
import type { DocumentLink } from '../../api/types'
import BasisPreview from '../../shared/BasisPreview.vue'
const props = defineProps<{ package: IssuePackage }>()
function issuedDocument(item: PackageItem): DocumentLink {
  if (!props.package.issuance) return item.document
  const check = props.package.checks.find(value => value.id === props.package.issuance!.check_id)
  // Null stays null, including a paper original with no accepted scan.
  // Never substitute a live/latest document if the issuing snapshot is absent.
  return check?.files.find(file => file.item_id === item.id)?.document ?? null
}
function label(kind: string) { return issueItemLabels[kind as IssueItemKind] || kind }
function time(value: string) { return new Intl.DateTimeFormat('ru-RU', { timeZone: 'Asia/Krasnoyarsk', dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) }
const workStates: Record<string, string> = { in_progress: 'В производстве', suspended: 'Приостановлена', completed: 'Завершена', without_execution: 'Без исполнения' }
</script>
<template>
  <section class="card stack-card"><h2>Работы и состав материала</h2><article v-for="work in package.works" :key="work.id" :data-issue-work="work.id" class="assignment-line"><div class="section-heading"><h3><RouterLink :to="`/expertises/${work.id}`">{{ work.registration_number }}</RouterLink></h3><span class="badge">{{ workStates[work.state] || work.state }}</span></div><p>{{ work.department.name }} · категория {{ work.category_code }}{{ work.is_commission ? ' · Комиссия' : '' }}</p><p>Требуются: {{ work.required_items.map(label).join(', ') || 'Регламент состава уточняется сервером' }}</p><template v-if="work.closure"><p>Подтверждённое окончание: {{ work.closure.ended_on || 'Дата неизвестна' }} · {{ work.closure.kind === 'completed' ? 'Завершение' : 'Без исполнения' }}</p><BasisPreview :document="work.closure.document" heading="Принятый итоговый документ" empty-text="Итоговый документ не указан." accepted-label="При окончании работы подтверждена" /></template><p v-else class="message">Подтверждённого окончания нет.</p><div v-for="kind in work.required_items" :key="kind"><p>{{ label(kind) }}: <span v-if="package.content.items.some(item => item.expertise_id === work.id && item.kind === kind)">указан в составе</span><span v-else class="badge badge-amber">не указан</span></p></div><div v-for="item in package.content.items.filter(item => item.expertise_id === work.id)" :key="item.id" class="inset-form"><h4>{{ label(item.kind) }}</h4><BasisPreview :document="issuedDocument(item)" :heading="label(item.kind)" :empty-text="package.issuance ? 'Документ принятой проверки недоступен.' : 'Документ не указан.'" :accepted-label="package.issuance ? 'При выдаче подтверждена' : undefined" /><p>{{ item.note }}</p></div><ul v-if="package.readiness.blockers.some(item => item.expertise_id === work.id)"><li v-for="(item, index) in package.readiness.blockers.filter(item => item.expertise_id === work.id)" :key="index">{{ item.message }}</li></ul></article><p v-if="!package.works.length" class="muted">Сервер не вернул работ для этого комплекта.</p></section>
  <section data-package-check-history class="card stack-card"><h2>Проверки и принятые файлы</h2><div v-for="check in package.checks" :key="check.id" class="assignment-line"><h3>{{ time(check.created_at) }} · {{ check.actor?.full_name || 'Сотрудник не указан' }}</h3><p>{{ check.reason }}</p><p class="muted compact">Редакция состава: {{ package.content_history.find(item => item.id === check.revision_id)?.number ?? 'Неизвестна' }}</p><p v-for="item in check.works" :key="item.expertise_id">{{ package.works.find(work => work.id === item.expertise_id)?.registration_number || 'Работа' }} · окончание {{ item.closure_id }}</p><BasisPreview v-for="(file, index) in check.files" :key="`${file.item_id || file.closure_id}-${index}`" :document="file.document" :heading="file.closure_id ? 'Принятый результат' : 'Принятое приложение'" accepted-label="При проверке комплекта подтверждена" /><p v-if="!check.files.length" class="muted">Электронные файлы в этой проверке не зафиксированы.</p></div><p v-if="!package.checks.length" class="muted">Проверок ещё нет.</p></section>
  <section class="card stack-card"><h2>История редакций состава</h2><details v-for="revision in package.content_history" :key="revision.id" class="assignment-line"><summary>Редакция {{ revision.number }} · {{ time(revision.created_at) }} · {{ revision.actor?.full_name || 'Сотрудник не указан' }}</summary><p class="issue-text">{{ revision.materials_description || 'Описание материалов не указано' }}</p><p>{{ revision.note }}</p><div v-for="item in revision.items" :key="item.id"><p>{{ label(item.kind) }} · {{ package.works.find(work => work.id === item.expertise_id)?.registration_number || 'Работа' }}</p><BasisPreview :document="item.document" :heading="label(item.kind)" /><p>{{ item.note }}</p></div><p>Основание: {{ revision.reason }}</p></details></section>
</template>
<style scoped>.issue-text { white-space: pre-wrap; overflow-wrap: anywhere; }</style>
